WITH flattened_attrs AS (SELECT id, customer_id, created_at, coupon_codes, items, ship_to, TRANSFORM(items, li -> li.product_id) AS product_ids, ship_to.zip AS ship_zip, AGGREGATE(items, 0D, (acc, li) -> acc + li.qty * li.price, acc -> ROUND(acc, 2)) AS basket_amount, COALESCE(attributes['device'], 'none') AS device_or_default, FORALL(items, li -> li.qty <= 5) AS all_small_qty FROM carts) SELECT *, LAST_VALUE(device_or_default) IGNORE NULLS OVER (ORDER BY basket_amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_device_or_default, NTILE(5) OVER (PARTITION BY customer_id ORDER BY basket_amount DESC, id) AS basket_amount_bucket, MAX(basket_amount) OVER (PARTITION BY MONTH(created_at), customer_id ORDER BY CAST(created_at AS BIGINT) RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW) AS basket_amount_max_1h, SUM(basket_amount) OVER (PARTITION BY customer_id ORDER BY created_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_basket_amount, PERCENT_RANK() OVER (PARTITION BY customer_id ORDER BY basket_amount NULLS LAST) AS basket_amount_percent_rank FROM flattened_attrs;
